import { useEffect, useState } from "react";
import { StyleSheet, View } from "react-native";
import { formatMs, now } from "../../clock";
import { Button } from "../../ui/Button";
import { Card } from "../../ui/Card";
import { InfoRow } from "../../ui/InfoRow";
import { Notice } from "../../ui/Notice";
import { space } from "../../ui/theme";
import { Picture } from "./Picture";
import * as js from "./pixels";
import * as native from "./pixels.lucent";

/** The image the demo times, in pixels a side. */
const SIZE = 512;

/** The preview's size, smaller: the BMPs cross to JavaScript as base64. */
const PREVIEW = 256;

interface Timing {
  native: number;
  js: number;
  same: boolean;
}

const tick = () => new Promise<void>((resolve) => setTimeout(resolve, 16));

/** Best of three runs, letting the screen draw between them. */
async function best(run: (size: number) => number): Promise<{ ms: number; checksum: number }> {
  let ms = Infinity;
  let checksum = 0;

  for (let i = 0; i < 3; i++) {
    await tick();

    const start = now();
    checksum = run(SIZE);
    ms = Math.min(ms, now() - start);
  }

  return { ms, checksum };
}

export function ComputeDemo() {
  const [preview, setPreview] = useState<native.Preview | null>(null);
  const [timing, setTiming] = useState<Timing | null>(null);
  const [running, setRunning] = useState(false);

  async function run() {
    setRunning(true);
    setTiming(null);

    setPreview(native.preview(PREVIEW));

    const lucent = await best(native.run);
    const javascript = await best(js.run);
    setTiming({
      native: lucent.ms,
      js: javascript.ms,
      same: lucent.checksum === javascript.checksum,
    });

    setRunning(false);
  }

  useEffect(() => {
    void run();
  }, []);

  return (
    <>
      {preview ? (
        <Card title="Drawn and filtered natively">
          <View style={styles.pictures}>
            <Picture label="Picture" base64={preview.picture} />
            <Picture label="Edges" base64={preview.edges} />
          </View>
        </Card>
      ) : null}

      <Card title={`${SIZE} × ${SIZE} pixels, best of 3`}>
        {timing ? (
          <>
            <InfoRow
              testID="compute-lucent"
              label="Lucent (C++)"
              value={`${formatMs(timing.native)} ms`}
            />
            <InfoRow
              testID="compute-js"
              label="JavaScript (Hermes)"
              value={`${formatMs(timing.js)} ms`}
            />
            <InfoRow
              label="Speedup"
              value={`${(timing.js / Math.max(timing.native, 0.001)).toFixed(1)}x`}
            />

            <Notice
              testID="compute-same"
              tone={timing.same ? "success" : "danger"}
              title={timing.same ? "Same pixels from both" : "The results differ"}
            />
          </>
        ) : (
          <Notice title="Timing both…" />
        )}

        {__DEV__ ? (
          <Notice
            tone="warning"
            title="Debug build"
            message="Use a Release build for representative numbers."
          />
        ) : null}

        <Button
          testID="compute-run"
          label="Run again"
          variant="secondary"
          busy={running}
          onPress={() => void run()}
        />
      </Card>
    </>
  );
}

const styles = StyleSheet.create({
  pictures: { flexDirection: "row", gap: space.md },
});
